s=s.replace("{isCollections?'SEU ESPAÇO DE INSPIRAÇÃO':'9 BIBLIOTECAS. UM SÓ FLUXO.'}", "{isCollections?'SEU ESPAÇO DE INSPIRAÇÃO':'UM ESPAÇO. INFINITAS IDEIAS.'}")
